export { FallbackChain } from "./fallback-chain";
export { fallbackChainChineseLabels, fallbackChainEnglishLabels } from "./fallback-chain-labels";
export type { FallbackAttempt, FallbackAttemptStatus, FallbackChainDetail, FallbackChainEnd, FallbackChainLabels, FallbackChainProps, } from "./fallback-chain-types";

"use client";
import { useEffect, useMemo, useState, type ReactElement, type ReactNode } from "react";
import { Badge, type BadgeStatus } from "@ui/badge";
import { Button } from "@ui/button";
import { Popover, PopoverContent, PopoverTitle, PopoverTrigger } from "@ui/popover";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { FallbackBranches } from "./fallback-chain-branches";
import { fallbackChainEnglishLabels } from "./fallback-chain-labels";
import type { FallbackAttempt, FallbackAttemptStatus, FallbackChainDetail, FallbackChainProps, } from "./fallback-chain-types";
import styles from "./fallback-chain.module.css";
const badgeTones: Record<FallbackAttemptStatus, BadgeStatus> = {
    waiting: "neutral", trying: "info", failed: "danger", answered: "success", skipped: "neutral",
};
const segments = Array.from({ length: 40 }, (_, index) => index);
function nonnegative(value?: number) {
    return value !== undefined && Number.isFinite(value) && value >= 0 ? value : undefined;
}
function useAttemptClock(startedAt: number | undefined, now: number | undefined) {
    const [clock, setClock] = useState<{
        startedAt: number;
        time: number;
    }>();
    useEffect(() => {
        if (startedAt === undefined || now !== undefined)
            return;
        const tick = () => setClock({ startedAt, time: Date.now() });
        const initial = window.setTimeout(tick, 0);
        const interval = window.setInterval(tick, 100);
        return () => {
            window.clearTimeout(initial);
            window.clearInterval(interval);
        };
    }, [now, startedAt]);
    return now ?? (clock && clock.startedAt === startedAt ? clock.time : startedAt) ?? 0;
}
function elapsed(attempt: FallbackAttempt, now: number) {
    const recorded = nonnegative(attempt.durationMs);
    const startedAt = nonnegative(attempt.startedAt);
    if (recorded === undefined && attempt.status === "trying" && startedAt !== undefined) {
        return Math.max(0, now - startedAt);
    }
    return recorded;
}
function Details({ name, subtitle, icon, badge, text, rows }: {
    name: string;
    subtitle?: string;
    icon?: ReactNode;
    badge?: ReactNode;
    text?: string;
    rows: readonly FallbackChainDetail[];
}) {
    return <div className={styles.details}>
    <div className={styles.detailHeader}>
      {icon && <span className={styles.detailIcon} aria-hidden="true">{icon}</span>}
      <div className={styles.detailName}>
        <PopoverTitle className={styles.detailTitle} render={<strong />}>{name}</PopoverTitle>
        {subtitle && <span>{subtitle}</span>}
      </div>
      {badge}
    </div>
    {text && <p className={styles.quote}>{text}</p>}
    {rows.length > 0 && <dl className={styles.detailRows}>
      {rows.map(({ label, value }, index) => <div key={index}>
        <dt>{label}</dt><dd>{value}</dd>
      </div>)}
    </dl>}
  </div>;
}
function NodeDetails({ children, content }: {
    children: ReactElement;
    content: ReactNode;
}) {
    return <Popover trigger="hover">
    <PopoverTrigger render={children}/>
    <PopoverContent sideOffset={8} className={styles.detailPopover}>{content}</PopoverContent>
  </Popover>;
}
export function FallbackChain({ attempts, title, route, request, response, now, onRetry, labels = fallbackChainEnglishLabels, locale = "en", className, }: FallbackChainProps) {
    const RouteIcon = useIcon("corner-down-right");
    const MessageIcon = useIcon("message-circle");
    const ClockIcon = useIcon("clock");
    const RetryIcon = useIcon("rotate-ccw");
    const tryingIndex = attempts.findIndex((attempt) => attempt.status === "trying");
    const trying = attempts[tryingIndex];
    const liveStart = nonnegative(trying?.durationMs) === undefined ? nonnegative(trying?.startedAt) : undefined;
    const clock = useAttemptClock(liveStart, nonnegative(now));
    const answered = attempts.find((attempt) => attempt.status === "answered");
    const hasModels = attempts.length > 0;
    const exhausted = attempts.some(({ status }) => status === "failed")
        && attempts.every(({ status }) => status === "failed" || status === "skipped");
    const allSkipped = hasModels && attempts.every(({ status }) => status === "skipped");
    const tried = attempts.filter(({ status }) => status !== "waiting" && status !== "skipped").length;
    const nextIndex = tryingIndex < 0 ? -1 : attempts.findIndex(({ status }, index) => index > tryingIndex && status === "waiting");
    const summaryStatus = answered ? "answered" : exhausted ? "failed" : allSkipped ? "skipped" : trying ? "trying" : "waiting";
    const summaryText = summaryStatus === "trying" ? labels.attempt(tryingIndex + 1, attempts.length)
        : exhausted ? labels.exhausted : labels[summaryStatus];
    const formatters = useMemo(() => ({
        ms: new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }),
        s: new Intl.NumberFormat(locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }),
        usd: new Intl.NumberFormat(locale, { style: "currency", currency: "USD", minimumFractionDigits: 0, maximumFractionDigits: 4 }),
    }), [locale]);
    function duration(value: number) {
        return value < 1000
            ? labels.duration(formatters.ms.format(value), "ms")
            : labels.duration(formatters.s.format(value / 1000), "s");
    }
    function cost(value: number) {
        return value > 0 && value < 0.0001
            ? `<${formatters.usd.format(0.0001)}`
            : formatters.usd.format(value);
    }
    const totalTime = duration(attempts.reduce((total, attempt) => total + (elapsed(attempt, clock) ?? 0), 0));
    const totalCost = cost(attempts.reduce((total, attempt) => total + (nonnegative(attempt.costUsd) ?? 0), 0));
    const outputTokens = nonnegative(answered?.outputTokens);
    const output = outputTokens === undefined ? undefined : labels.tokens(formatters.ms.format(outputTokens));
    const responseStatus = summaryStatus === "trying" ? "waiting" : summaryStatus;
    const responseText = output ?? (exhausted ? labels.exhausted
        : responseStatus === "waiting" ? labels.responseWaiting : labels[responseStatus]);
    const responseDetails = <Details name={response?.name ?? labels.response} subtitle={answered ? labels.fromModel(answered.model) : responseText} icon={response?.icon} badge={<Badge size="sm" status={badgeTones[responseStatus]}>
      {labels[responseStatus]}
    </Badge>} text={answered ? response?.text : undefined} rows={[
            { label: labels.totalTime, value: totalTime },
            { label: labels.totalCost, value: totalCost },
            { label: labels.attempts, value: labels.attemptCount(tried, attempts.length) },
            ...(output !== undefined ? [{ label: labels.output, value: output }] : []),
            ...(response?.details ?? []),
        ]}/>;
    return <section className={cn(styles.chain, className)} data-slot="fallback-chain" aria-label={title ?? labels.request}>
    <header className={styles.header}>
      <span className={styles.title}>{title ?? labels.request}</span>
      <div className={styles.summary}>
        <span className={styles.state} data-status={summaryStatus} role="status">
          <span className={styles.dot} aria-hidden="true"/>
          {summaryText}
        </span>
        <span className={styles.metric}><ClockIcon size={12} aria-hidden="true"/>{totalTime}</span>
        <span className={styles.metric}>{totalCost}</span>
        {hasModels && <Popover>
          <PopoverTrigger className={styles.compactResponse} data-status={summaryStatus} aria-label={`${labels.response}: ${responseText}`}>
            <MessageIcon size={14} aria-hidden="true"/>
          </PopoverTrigger>
          <PopoverContent className={styles.detailPopover}>{responseDetails}</PopoverContent>
        </Popover>}
        {exhausted && onRetry && <Button variant="secondary" size="xs" leadingIcon={RetryIcon} onClick={onRetry}>{labels.retry}</Button>}
      </div>
    </header>
    {hasModels ? <div className={styles.flow}>
      <NodeDetails content={<Details name={request?.name ?? labels.request} subtitle={route} icon={request?.icon} text={request?.text} rows={[...(request?.details ?? []), { label: labels.attempts, value: labels.attemptCount(tried, attempts.length) }]}/>}>
        <button type="button" className={cn(styles.endpoint, styles.request)}>
          <span className={styles.endpointIcon} aria-hidden="true"><RouteIcon size={15}/></span>
          <span className={styles.endpointText}>
            <strong>{labels.request}</strong>
            {route && <span className={styles.route} title={route}>{route}</span>}
          </span>
        </button>
      </NodeDetails>
      <FallbackBranches attempts={attempts} layout="incoming"/>
      <FallbackBranches attempts={attempts} layout="tree"/>
      <ol className={styles.models} role="list" aria-label={labels.models}>
        {attempts.map((attempt, index) => {
                const time = elapsed(attempt, clock);
                const timeLabel = time === undefined ? undefined : duration(time);
                const costUsd = nonnegative(attempt.costUsd);
                const costLabel = costUsd === undefined ? undefined : cost(costUsd);
                const budget = nonnegative(attempt.timeoutMs);
                const progress = budget && time !== undefined
                    ? Math.round(Math.min(1, time / budget) * segments.length)
                    : attempt.status === "answered" ? segments.length : 0;
                const statusLabel = index === nextIndex ? labels.upNext : labels[attempt.status];
                const tokens = nonnegative(attempt.outputTokens);
                const detail = attempt.status === "answered" && tokens !== undefined
                    ? labels.tokens(formatters.ms.format(tokens)) : attempt.reason;
                const statusText = detail ? `${statusLabel} · ${detail}` : statusLabel;
                const displayStatus = attempt.reason && attempt.status === "failed" ? attempt.reason : statusText;
                const rows: FallbackChainDetail[] = [{ label: labels.model, value: attempt.model }];
                const budgetLabel = budget ? labels.timeBudget(timeLabel, duration(budget)) : timeLabel;
                if (budgetLabel !== undefined)
                    rows.push({ label: labels.time, value: budgetLabel });
                if (costLabel !== undefined)
                    rows.push({ label: labels.cost, value: costLabel });
                rows.push(...(attempt.details ?? []));
                if (attempt.reason)
                    rows.push({ label: labels.why, value: attempt.reason });
                return <li key={attempt.id}>
            <NodeDetails content={<Details name={attempt.provider ?? attempt.model} subtitle={attempt.region} icon={attempt.providerIcon ?? attempt.icon} badge={<Badge size="sm" status={badgeTones[attempt.status]}>{labels[attempt.status]}</Badge>} rows={rows}/>}>
              <button type="button" className={styles.model} data-status={attempt.status} aria-label={[attempt.model, attempt.provider, statusText, timeLabel, costLabel].filter(Boolean).join(" · ")}>
                <span className={styles.logo} aria-hidden="true">
                  {attempt.icon}<span className={styles.order} data-icon={attempt.icon != null || undefined}>{index + 1}</span>
                </span>
                <span className={styles.modelText}>
                  <span className={styles.modelHeading}>
                    <strong title={attempt.model}>{attempt.model}</strong>
                    {attempt.provider && <span className={styles.provider} title={attempt.provider}>{attempt.provider}</span>}
                  </span>
                  <span className={styles.modelStatus} title={displayStatus}>{displayStatus}</span>
                </span>
                <span className={styles.modelMetrics}>
                  <span>{timeLabel ?? "–"}</span>
                  {costLabel !== undefined && <span>{costLabel}</span>}
                </span>
                <span className={styles.segments} aria-hidden="true">
                  {segments.map((segment) => <i key={segment} data-filled={segment < progress || undefined}/>)}
                </span>
              </button>
            </NodeDetails>
          </li>;
            })}
      </ol>
      <FallbackBranches attempts={attempts} layout="outgoing"/>
      <NodeDetails content={responseDetails}>
        <button type="button" className={cn(styles.endpoint, styles.response)} data-status={responseStatus}>
          <span className={styles.endpointIcon} aria-hidden="true"><MessageIcon size={15}/></span>
          <span className={styles.endpointText}>
            <strong>{labels.response}</strong>
            <span title={responseText}>{responseText}</span>
          </span>
        </button>
      </NodeDetails>
    </div> : <div className={styles.empty}>{labels.noAttempts}</div>}
  </section>;
}

import type { ReactNode } from "react";
export type FallbackAttemptStatus = "waiting" | "trying" | "failed" | "answered" | "skipped";
export interface FallbackChainDetail {
    label: string;
    value: string;
}
export interface FallbackChainEnd {
    name: string;
    icon?: ReactNode;
    text?: string;
    details?: readonly FallbackChainDetail[];
}
export interface FallbackAttempt {
    id: string;
    model: string;
    provider?: string;
    region?: string;
    icon?: ReactNode;
    providerIcon?: ReactNode;
    status: FallbackAttemptStatus;
    reason?: string;
    /** Unix timestamp in milliseconds. Used to time a running attempt. */
    startedAt?: number;
    durationMs?: number;
    timeoutMs?: number;
    costUsd?: number;
    outputTokens?: number;
    details?: readonly FallbackChainDetail[];
}
export interface FallbackChainLabels extends Record<FallbackAttemptStatus, string> {
    request: string;
    response: string;
    responseWaiting: string;
    exhausted: string;
    noAttempts: string;
    upNext: string;
    retry: string;
    models: string;
    model: string;
    time: string;
    cost: string;
    attempts: string;
    totalTime: string;
    totalCost: string;
    output: string;
    why: string;
    attempt: (current: number, total: number) => string;
    attemptCount: (current: number, total: number) => string;
    tokens: (formattedCount: string) => string;
    fromModel: (model: string) => string;
    duration: (formattedValue: string, unit: "ms" | "s") => string;
    timeBudget: (elapsed: string | undefined, limit: string) => string;
}
export interface FallbackChainProps {
    /** Attempts in routing order, with an ID that is stable across updates. */
    attempts: readonly FallbackAttempt[];
    title?: string;
    route?: string;
    request?: FallbackChainEnd;
    response?: FallbackChainEnd;
    /** Override the running clock with a Unix timestamp in milliseconds. */
    now?: number;
    /** Called when the route is exhausted and the user requests another run. */
    onRetry?: () => void;
    labels?: FallbackChainLabels;
    locale?: string;
    className?: string;
}

import type { FallbackAttempt, FallbackAttemptStatus } from "./fallback-chain-types";
import styles from "./fallback-chain.module.css";
const width = 48;
const treeWidth = 44;
const rowHeight = 60;
const rowGap = 10;
function Branch({ path, status }: {
    path: string;
    status: FallbackAttemptStatus;
}) {
    return <g data-status={status}>
    <path className={styles.line} d={path} pathLength={100}/>
    {status === "trying" && <path className={styles.beam} d={path} pathLength={100}/>}
  </g>;
}
export function FallbackBranches({ attempts, layout }: {
    attempts: readonly FallbackAttempt[];
    layout: "incoming" | "outgoing" | "tree";
}) {
    const modelsHeight = attempts.length * (rowHeight + rowGap) - rowGap;
    const middle = modelsHeight / 2;
    const tree = layout === "tree";
    const outgoing = layout === "outgoing";
    const height = tree ? modelsHeight + rowGap : modelsHeight;
    const viewWidth = tree ? treeWidth : width;
    return (<svg className={styles[layout]} viewBox={`0 0 ${viewWidth} ${height}`} width={viewWidth} height={height} preserveAspectRatio="none" aria-hidden="true">
      {attempts.map((attempt, index) => {
            const rowCenter = index * (rowHeight + rowGap) + rowHeight / 2;
            const from = outgoing ? rowCenter : middle;
            const to = outgoing ? middle : rowCenter;
            const treeCenter = rowCenter + rowGap;
            const path = tree
                ? `M20 0V${treeCenter - 10}Q20 ${treeCenter} 30 ${treeCenter}H${treeWidth}`
                : `M0 ${from}C26 ${from} 22 ${to} ${width} ${to}`;
            return <Branch key={attempt.id} path={path} status={outgoing && attempt.status !== "answered" ? "waiting" : attempt.status}/>;
        })}
    </svg>);
}

.chain {
  --chain-card: var(--surface-floating);
  --chain-surface: color-mix(in oklab, var(--surface-floating) 80%, var(--surface-base));
  --chain-row-height: 60px;
  --chain-row-gap: 10px;
  --chain-line: color-mix(in oklab, var(--fg-default) 19%, transparent);
  --chain-shadow: 0 0 0 0.5px var(--border-subtle), var(--shadow-control);
  container-type: inline-size;
  inline-size: 100%;
  min-inline-size: 0;
  color: var(--fg-default);
  font-size: 13px;
  line-height: 1.35;
}

.header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 6px 12px;
  min-block-size: 28px;
  margin-block-end: 10px;
  padding-inline: 2px;
}

.title {
  overflow-wrap: anywhere;
  font-weight: 500;
}

.summary,
.state,
.metric {
  display: flex;
  align-items: center;
}

.summary {
  flex-wrap: wrap;
  gap: 6px 12px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.state {
  gap: 6px;
  color: var(--fg-subtle);
}

.dot {
  inline-size: 6px;
  block-size: 6px;
  border-radius: 50%;
  background: var(--chain-tone, var(--chain-line));
}

.metric {
  gap: 4px;
  padding-inline-start: 12px;
  border-inline-start: 1px solid var(--border-subtle);
  white-space: nowrap;
}

.metric svg { color: var(--fg-subtle); }

.flow,
.empty {
  border-radius: 12px;
  background-color: var(--chain-surface);
  background-image: radial-gradient(var(--border-subtle) 0.8px, transparent 0.8px);
  background-position: 6px 6px;
  background-size: 12px 12px;
  box-shadow: var(--chain-shadow);
}

.flow {
  display: grid;
  grid-template-columns: min(20%, 140px) 48px minmax(0, 1fr) 48px min(20%, 140px);
  align-items: center;
  padding: 22px 16px;
}

.empty {
  display: grid;
  place-items: center;
  min-block-size: 110px;
  padding: 16px;
  color: var(--fg-muted);
}

.endpoint,
.model {
  position: relative;
  min-inline-size: 0;
  border: 0;
  border-radius: 10px;
  background-color: var(--chain-card);
  box-shadow: var(--chain-shadow);
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) ease, box-shadow var(--motion-duration-fast) ease;
}

.endpoint:focus-visible,
.model:focus-visible,
.compactResponse:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
  z-index: 1;
}

.endpoint {
  display: flex;
  align-items: center;
  gap: 8px;
  min-block-size: 52px;
  padding-inline: 8px;
}

.endpointIcon,
.logo,
.detailIcon {
  display: grid;
  flex: none;
  place-items: center;
  inline-size: 24px;
  block-size: 24px;
  border-radius: 7px;
  background: var(--surface-floating);
  box-shadow: var(--chain-shadow);
}

.request .endpointIcon {
  color: var(--fg-brand);
  background: var(--info-surface);
  box-shadow: none;
}

.response[data-status="waiting"] {
  background: var(--chain-surface);
  color: var(--fg-subtle);
}

.response[data-status="answered"] .endpointIcon,
.response[data-status="failed"] .endpointIcon {
  color: var(--chain-tone);
  background: color-mix(in oklab, var(--chain-tone) 10%, var(--surface-floating));
}

.endpointText,
.modelText { display: grid; min-inline-size: 0; }

.endpointText > *,
.modelHeading > *,
.modelStatus {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.endpointText strong,
.modelHeading strong {
  font-size: 12.5px;
  font-weight: 500;
}

.endpointText > span,
.provider {
  color: var(--fg-subtle);
  font-size: 11px;
}

.endpointText .route { font-family: var(--font-mono, monospace); font-size: 10px; }

.models {
  display: grid;
  gap: var(--chain-row-gap);
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.model {
  display: grid;
  grid-template: minmax(0, 1fr) 5px / 26px minmax(0, 1fr) auto;
  align-items: center;
  gap: 5px 10px;
  inline-size: 100%;
  block-size: var(--chain-row-height);
  padding: 7px 12px 7px 10px;
}

.chain [data-status="trying"] { --chain-tone: var(--info-strong); }
.chain [data-status="failed"] { --chain-tone: var(--danger-strong); }
.chain [data-status="answered"] { --chain-tone: var(--success-strong); }

.model[data-status="trying"],
.model[data-status="answered"] {
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--chain-tone) 50%, transparent),
    0 0 0 4px color-mix(in oklab, var(--chain-tone) 10%, transparent), var(--chain-shadow);
}

.model[data-status="waiting"],
.model[data-status="skipped"] { color: var(--fg-subtle); }

.model[data-status="waiting"] .logo,
.model[data-status="skipped"] .logo,
.model[data-status="failed"] .logo { opacity: 0.75; }

.logo {
  position: relative;
  grid-row: 1 / 3;
  inline-size: 26px;
  block-size: 26px;
}

.logo svg { inline-size: 14px; block-size: 14px; }

.order {
  display: grid;
  place-items: center;
  min-inline-size: 13px;
  block-size: 13px;
  padding-inline: 2px;
  border-radius: 999px;
  color: var(--fg-subtle);
  font-size: 8.5px;
  font-weight: 500;
}

.order[data-icon] {
  position: absolute;
  inset-inline-end: -5px;
  inset-block-end: -4px;
  background: var(--surface-floating);
  box-shadow: 0 0 0 1px var(--surface-floating);
}

.model[data-status="trying"] .order { color: var(--fg-on-info-strong); background: var(--info-strong); }
.model[data-status="failed"] .order { color: var(--fg-on-danger-strong); background: var(--danger-strong); }
.model[data-status="answered"] .order { color: var(--fg-on-success-strong); background: var(--success-strong); }

.modelHeading {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.modelHeading strong { flex-shrink: 0; max-inline-size: 100%; }

.modelStatus,
.modelMetrics {
  color: var(--fg-subtle);
  font-size: 11.5px;
}

.modelStatus { line-height: 1.35; }
.model[data-status="trying"] .modelStatus { color: var(--fg-brand); }
.model[data-status="failed"] .modelStatus { color: var(--fg-danger); }
.model[data-status="answered"] .modelStatus { color: var(--fg-success); }

.modelMetrics {
  display: grid;
  justify-items: end;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.modelMetrics > :first-child { color: var(--fg-default); }
.model[data-status="waiting"] .modelMetrics > :first-child,
.model[data-status="skipped"] .modelMetrics > :first-child { color: var(--fg-subtle); }

.segments {
  display: flex;
  grid-column: 2 / -1;
  gap: clamp(1px, 0.34cqi, 2px);
  block-size: 5px;
}

.segments i {
  flex: 1 1 0;
  border-radius: 1px;
  background: var(--border-subtle);
}

.segments i[data-filled] { background: color-mix(in oklab, var(--chain-tone, var(--neutral)) 76%, transparent); }
.model[data-status="failed"] .segments i[data-filled] {
  background: color-mix(in oklab, var(--chain-tone) 38%, transparent);
}

.incoming,
.outgoing,
.tree {
  display: block;
  inline-size: 100%;
  overflow: visible;
  pointer-events: none;
}

.tree,
.compactResponse { display: none; }

.line,
.beam {
  fill: none;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.line {
  stroke: var(--chain-line);
  stroke-dasharray: 1.2 3;
}

[data-status="failed"] > .line { stroke: color-mix(in oklab, var(--chain-tone) 52%, transparent); stroke-dasharray: 3.5 3.5; }
[data-status="trying"] > .line { stroke: color-mix(in oklab, var(--chain-tone) 45%, transparent); stroke-dasharray: none; }
[data-status="answered"] > .line { stroke: var(--chain-tone); stroke-dasharray: none; }

.beam {
  stroke: var(--chain-tone);
  stroke-width: 2.25;
  stroke-dasharray: 26 100;
  animation: traverse 1.4s ease-in-out infinite;
}

@keyframes traverse {
  from { stroke-dashoffset: 26; }
  to { stroke-dashoffset: -100; }
}

.detailPopover.detailPopover {
